    def loss(f):
        d = _b_basis(u, f)
        return np.linalg.norm(v - d @ _fit(d, v))
    grid = np.linspace(0.5, 7.0, 66)
    best = grid[np.argmin([loss(f) for f in grid])]
    (left, right) = (best - 0.1, best + 0.1)
    for _ in range(20):
        (a, b) = ((2 * left + right) / 3, (left + 2 * right) / 3)
        if loss(a) < loss(b):
